<section class="warehouse-page">
<header class="warehouse-hero">
  <div><p class="eyebrow">Inventory OS · Warehouse</p><div class="title-line"><h2>{{warehouse.name}}</h2><span class="warehouse-code">{{warehouse.code}}</span><span class="state-pill" :class="warehouse.fulfillment_state">{{warehouse.fulfillment_state_label}}</span></div><p class="subtitle">{{warehouse.name_en||warehouse.code}} · {{warehouse.role_label}} · {{warehouseAddress}}</p></div>
  <div class="hero-actions page-header-actions"><Link class="button ghost" href="/inventory/list">仓库清单</Link><Link class="button primary" href="/inventory/sync">导入库存</Link></div>
</header>
<nav class="warehouse-tabs" aria-label="Warehouse 360">
  <button type="button" :class="{active:activeTab==='overview'}" @click="activeTab='overview'">总览</button>
  <button type="button" :class="{active:activeTab==='inventory'}" @click="activeTab='inventory'">库存</button>
  <button type="button" :class="{active:activeTab==='inbound'}" @click="activeTab='inbound'">在途<span v-if="inboundProjection?.summary.in_transit_batches" class="tab-count">{{inboundProjection.summary.in_transit_batches}}</span></button>
  <button type="button" :class="{active:activeTab==='costs'}" @click="activeTab='costs'">成本</button>
  <button type="button" :class="{active:activeTab==='shipping'}" @click="activeTab='shipping'">发货</button>
  <button type="button" :class="{active:activeTab==='exceptions'}" @click="activeTab='exceptions'">异常<span v-if="inventoryWarnings.length+reconciliationReviews.length" class="tab-count">{{inventoryWarnings.length+reconciliationReviews.length}}</span></button>
  <button type="button" :class="{active:activeTab==='config'}" @click="activeTab='config'">配置</button>
</nav>
<div v-if="activeTab==='overview'" class="kpi-grid">
  <article><span>库存 SKU</span><strong>{{kpis.skus}}</strong><small>当前仓库商品</small></article>
  <article><span>当前库存</span><strong>{{kpis.onHand}}</strong><small>仓库实物数量</small></article>
  <article><span>可用库存</span><strong>{{kpis.available}}</strong><small>扣除预留后</small></article>
  <article><span>库存预警</span><strong>{{kpis.low+kpis.out}}</strong><small>{{kpis.low}} 紧张 · {{kpis.out}} 无货</small></article>
  <article><span>最后同步</span><strong class="sync-time">{{lastSync}}</strong><small>最近确认库存快照</small></article>
</div>
<section v-if="activeTab==='overview'" class="overview-grid">
  <article class="overview-card"><div class="overview-card-head"><div><p class="section-kicker">INVENTORY STATUS</p><h3>库存状态</h3></div><button type="button" class="text-button" @click="activeTab='inventory'">查看库存 →</button></div><div class="overview-stat-list"><div><span>正常库存</span><strong>{{Math.max(kpis.skus-kpis.low-kpis.out,0)}}</strong></div><div><span>库存紧张</span><strong>{{kpis.low}}</strong></div><div><span>无货</span><strong>{{kpis.out}}</strong></div><div><span>清仓商品</span><strong>{{clearanceProducts.length}}</strong></div></div></article>
  <article class="overview-card"><div class="overview-card-head"><div><p class="section-kicker">LATEST COST</p><h3>最近成本</h3></div><button type="button" class="text-button" @click="activeTab='costs'">查看成本 →</button></div><template v-if="latestCostSummary.length"><div v-for="summary in latestCostSummary" :key="summary.currency" class="overview-cost-row"><strong>{{summary.currency}} {{money(summary.total)}}</strong><span>运费 {{money(summary.shipping)}} · 出库 {{money(summary.parcel_outbound)}} · 仓储 {{money(summary.storage)}}</span></div></template><div v-else class="overview-empty">暂无月度成本记录</div></article>
  <article class="overview-card overview-wide"><div class="overview-card-head"><div><p class="section-kicker">QUICK ACTIONS</p><h3>常用操作</h3></div></div><div class="quick-actions"><Link class="button ghost" href="/inventory/sync">导入 / 更新库存</Link><button type="button" class="button ghost" @click="activeTab='costs'">导入成本表</button><button type="button" class="button ghost" @click="activeTab='exceptions'">查看异常</button><button type="button" class="button ghost" @click="activeTab='config'">仓库配置</button></div></article>
</section>
<section v-if="activeTab==='inbound'" class="primary-panel inbound-panel">
  <div class="section-heading"><div><p class="section-kicker">INBOUND</p><h3>在途 / 入仓运输</h3><p>批次按“准备中 → 工厂打包 → 运输中 → 港口已到货 → 仓库已入库 → 正常发货”推进；只有最后一步“正常发货”才激活可用库存。</p></div></div>
  <template v-if="inboundProjection">
    <div class="shipment-kpis inbound-kpis">
      <article><span>进行中批次</span><strong>{{inboundProjection.summary.in_transit_batches}}</strong><small>准备 / 打包 / 运输 / 到港</small></article>
      <article><span>进行中件数</span><strong>{{inboundProjection.summary.in_transit_units}}</strong><small>尚未进入可用库存</small></article>
      <article><span>仓库已入库</span><strong>{{inboundProjection.summary.received_batches}}</strong><small>待库存激活</small></article>
      <article><span>正常发货</span><strong>{{inboundProjection.summary.ready_batches}}</strong><small>库存已激活</small></article>
    </div>
    <div v-if="inboundProjection.batches.length" class="inbound-list">
      <article v-for="batch in inboundProjection.batches" :key="batch.id" class="inbound-batch">
        <div class="inbound-batch-head">
          <div><div class="inbound-title-line"><strong>{{batch.reference}}</strong><span class="inbound-status-pill" :class="`inbound-status-${batch.status}`">{{batch.status_label}}</span></div><small>{{batch.transport_mode==='sea'?'海运':batch.transport_mode==='air'?'空运':batch.transport_mode==='express'?'快递':batch.transport_mode}}</small></div>
          <div class="inbound-meta"><span>{{batch.carton_count??'—'}} 箱</span><span>{{batch.quantity_total}} 件</span><span v-if="batch.gross_weight_kg">{{batch.gross_weight_kg}} kg</span><span v-if="batch.volume_cbm">{{batch.volume_cbm}} CBM</span></div>
        </div>
        <div class="inbound-eta"><span>ETA</span><strong>{{batch.eta_date||'待确认'}}</strong><small v-if="batch.eta_is_estimated">Estimated</small><small v-if="batch.source_filename">证据：{{batch.source_filename}}</small></div>
        <div class="inbound-lifecycle" aria-label="入库批次状态流程">
          <div v-for="(status,index) in inboundProjection.statuses" :key="status.key" class="inbound-step" :class="{done:index<inboundStatusIndex(batch.status),active:index===inboundStatusIndex(batch.status)}"><span>{{index+1}}</span><small>{{status.label}}</small></div>
        </div>
        <div class="inbound-action-row">
          <div><span>当前状态</span><strong>{{batch.status_label}}</strong><small v-if="batch.received_on">仓库入库日：{{batch.received_on}}</small><small v-if="batch.status==='received'&&batch.activation_blocked_count>0" class="inbound-warning">还有 {{batch.activation_blocked_count}} 个待复核 SKU，暂不能激活库存</small></div>
          <button v-if="canOperate&&batch.next_status" type="button" class="button primary" :disabled="inboundAdvancing===batch.id||(batch.next_status==='ready'&&batch.activation_blocked_count>0)" @click="advanceInbound(batch)">{{inboundAdvancing===batch.id?'更新中…':batch.next_status_label}}</button>
          <span v-else-if="batch.status==='ready'" class="inbound-ready-mark">✓ 已进入正常发货</span>
        </div>
        <div class="table-shell"><table><thead><tr><th>SKU</th><th>产品</th><th>数量</th><th>证据</th><th>匹配</th><th>备注</th></tr></thead><tbody><tr v-for="item in batch.items" :key="item.id"><td><strong>{{item.canonical_sku||item.source_sku||'未识别'}}</strong><small v-if="item.source_sku&&item.source_sku!==item.canonical_sku">原始：{{item.source_sku}}</small></td><td>{{item.product_name||'—'}}</td><td>{{item.quantity}}</td><td>{{item.evidence_type==='actual_manifest'?'实际运输单':item.evidence_type==='planned_pi'?'PI 计划':'补充证据'}}</td><td><span class="source-pill" :class="{review:item.match_status!=='matched'}">{{item.match_status==='matched'?'已匹配':'待复核'}}</span></td><td>{{item.note||'—'}}</td></tr></tbody></table></div>
        <p v-if="batch.note" class="inbound-note">{{batch.note}}</p>
      </article>
    </div>
    <div v-else class="overview-empty">当前没有在途 / 入仓运输记录。</div>
  </template>
</section>
<section v-if="activeTab==='shipping'" class="primary-panel shipment-panel"><div class="section-heading"><div><p class="section-kicker">SHIPMENTS</p><h3>仓库发货</h3><p>这里仅展示当前仓库的真实 ERP Shipment，只读聚合；发货、审核、单号回传仍由 Logistics OS 负责。</p></div><Link class="button primary" :href="shipmentProjection?.logistics_url||'/logistics/oversea'">进入 Logistics OS →</Link></div><template v-if="shipmentProjection"><div class="shipment-kpis"><article><span>近 30 天</span><strong>{{shipmentProjection.counts.last_30d}}</strong><small>真实 Shipment</small></article><article><span>今日发货</span><strong>{{shipmentProjection.counts.today}}</strong><small>按 shipped_at</small></article><article><span>异常</span><strong>{{shipmentProjection.counts.exceptions}}</strong><small>当前仓库</small></article><article><span>累计记录</span><strong>{{shipmentProjection.counts.total}}</strong><small>ERP Shipment</small></article></div><div class="toolbar shipment-toolbar"><div class="search"><span>⌕</span><input v-model="shipmentQuery" placeholder="搜索订单号、Tracking、Carrier、国家、SKU" @keyup.enter="applyShipmentFilters"><button type="button" class="text-button" @click="applyShipmentFilters">搜索</button></div><select v-model="shipmentStatus" @change="applyShipmentFilters"><option value="all">全部状态</option><option value="shipped">已发货</option><option value="exception">异常</option><option value="pending">待发货</option><option value="completed">已完成</option></select></div><div v-if="filteredShipments.length" class="table-shell"><table class="shipment-table"><thead><tr><th>订单</th><th>发货时间</th><th>SKU / 数量</th><th>Tracking</th><th>Carrier</th><th>状态</th><th>目的国家</th><th>真实成本</th><th>来源</th></tr></thead><tbody><tr v-for="row in filteredShipments" :key="row.shipment_id"><td><Link v-if="row.order_url" class="order-link" :href="row.order_url"><strong>{{row.erp_order_id||`Order #${row.order_id}`}}</strong><small>Shipment #{{row.shipment_id}}</small></Link><template v-else><strong>Shipment #{{row.shipment_id}}</strong></template></td><td>{{row.shipped_at?new Date(row.shipped_at).toLocaleString('zh-CN'):'—'}}</td><td class="shipment-items">{{shipmentItemsLabel(row)}}</td><td><strong>{{row.tracking_number||'—'}}</strong></td><td>{{row.carrier||'—'}}<small v-if="row.service">{{row.service}}</small></td><td><span class="shipment-status" :class="`shipment-${row.shipment_status}`">{{shipmentStatusLabel(row.shipment_status)}}</span></td><td>{{row.destination_country||'—'}}</td><td>{{shipmentCostLabel(row)}}</td><td><span class="source-pill">ERP</span></td></tr></tbody></table></div><div v-else class="overview-empty">当前筛选条件下没有 Shipment 记录。</div><div v-if="shipmentProjection.pagination.total>0" class="shipment-pagination"><div class="shipment-pagination-meta"><span>共 {{shipmentProjection.pagination.total}} 条</span><span>第 {{shipmentProjection.pagination.page}} / {{shipmentProjection.pagination.last_page}} 页</span><label class="shipment-page-size">每页 <select v-model.number="shipmentPerPage" @change="changeShipmentPerPage"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select> 条</label><span>{{shipmentProjection.pagination.from}}–{{shipmentProjection.pagination.to}} / {{shipmentProjection.pagination.total}} 条</span></div><div class="shipment-pagination-actions"><button type="button" class="button ghost" :disabled="shipmentProjection.pagination.page<=1" @click="loadShipments(shipmentProjection.pagination.page-1)">上一页</button><button type="button" class="button ghost" :disabled="shipmentProjection.pagination.page>=shipmentProjection.pagination.last_page" @click="loadShipments(shipmentProjection.pagination.page+1)">下一页</button></div></div><div class="legacy-shipment-note"><div><strong>历史仓库发货记录</strong><p>Legacy 历史数据尚未接入；后续会单独导入为只读历史记录，不生成 Shipment、不改库存、不触发 Woo / 财务写入。</p></div><span>Legacy · {{shipmentProjection.legacy.status==='not_configured'?'待接入':shipmentProjection.legacy.status}}</span></div></template><div v-else class="overview-empty">Shipment Projection 暂不可用，请从 Logistics OS 查看真实发货。</div></section>
<section v-if="activeTab==='exceptions'" class="primary-panel exception-panel"><div class="section-heading"><div><p class="section-kicker">EXCEPTIONS</p><h3>异常与待复核</h3><p>只展示已有库存预警和真实账单核销 Review。</p></div></div><div class="exception-summary"><article><span>库存预警</span><strong>{{inventoryWarnings.length}}</strong></article><article><span>账单 Review / Excluded</span><strong>{{reconciliationReviews.length}}</strong></article></div><div v-if="inventoryWarnings.length" class="table-shell"><table><thead><tr><th>SKU / 产品</th><th>可用库存</th><th>状态</th><th>库位</th></tr></thead><tbody><tr v-for="i in inventoryWarnings" :key="i.id"><td><strong>{{i.product.sku}}</strong><small>{{i.product.name}}</small></td><td>{{i.quantity_available}}</td><td><span class="stock-badge" :class="`stock-${i.stock_status}`">{{i.stock_status_label}}</span></td><td>{{i.location||'—'}}</td></tr></tbody></table></div><div v-if="!inventoryWarnings.length && !reconciliationReviews.length" class="overview-empty">当前没有库存或成本异常。</div></section>
<div v-if="activeTab==='inventory'" class="inventory-mode-bar"><div><strong>库存工作台</strong><span>当前库存、备货与清仓共用一个工作区</span></div><div class="segmented"><button type="button" :class="{active:inventoryMode==='stock'}" @click="inventoryMode='stock'">当前库存 <b>{{warehouse.inventories.length}}</b></button><button type="button" :class="{active:inventoryMode==='restock'}" @click="inventoryMode='restock'">备货 <b>{{restockProjection?.summary.products_to_restock||0}}</b></button><button type="button" :class="{active:inventoryMode==='clearance'}" @click="inventoryMode='clearance'">清仓 <b>{{clearanceProducts.length}}</b></button></div></div>
<section v-if="activeTab==='inventory' && inventoryMode==='restock'" class="primary-panel restock-panel">
  <div class="section-heading"><div><p class="section-kicker">RESTOCK PLAN</p><h3>备货清单</h3><p>成熟仓库公式：MAX(过去4个月真实出货件数 - 当前可用库存, 0)。新品 / 历史缺货 SKU 可在“人工补充备货”中追加。</p></div><div class="section-actions"><button v-if="canOperate" type="button" class="button primary" :disabled="restockConfirming||!(restockProjection?.summary.products_to_restock)" @click="confirmRestockPlan">{{restockConfirming?'确认中…':'确认备货计划'}}</button></div></div>
  <div v-if="latestRestockPlan" class="restock-plan-snapshot"><div><span>最近已确认</span><strong>{{latestRestockPlan.reference}}</strong><small>{{latestRestockPlan.summary.snapshot_products}} 个 SKU · {{latestRestockPlan.summary.final_units}} 件</small></div><div><span>蓝标 SKU 覆盖</span><strong>{{latestRestockPlan.summary.label_sku_overrides}}</strong><small>与产品 SKU 不同</small></div><div><span>已知箱数</span><strong>{{latestRestockPlan.summary.cartons_known}}</strong><small v-if="latestRestockPlan.summary.products_missing_units_per_carton">{{latestRestockPlan.summary.products_missing_units_per_carton}} 个 SKU 待补“几个/箱”</small><small v-else>装箱数据完整</small></div></div>
  <div v-if="latestRestockPlan" class="restock-label-job-card">
    <div class="restock-label-job-copy">
      <span>BLUE LABEL GENERATOR</span>
      <template v-if="latestRestockLabelJob">
        <div class="restock-label-job-title"><strong>蓝标生成 · {{latestRestockLabelJob.status_label}}</strong><b :class="`job-${latestRestockLabelJob.status}`">{{latestRestockLabelJob.status_label}}</b></div>
        <p>{{latestRestockLabelJob.reference}} · {{latestRestockLabelJob.status_detail}}</p>
        <div class="blue-label-progress" :class="'progress-'+latestRestockLabelJob.status"><span :style="{width:latestRestockLabelJob.progress_percent+'%'}"></span></div>
        <small v-if="!latestRestockLabelJob.is_terminal">进度 {{latestRestockLabelJob.progress_percent}}%<template v-if="latestRestockLabelJob.expected_artifact_files"> · 已回传 {{latestRestockLabelJob.received_artifact_files}} / {{latestRestockLabelJob.expected_artifact_files}} 个文件</template><template v-if="latestRestockLabelJob.last_heartbeat_at"> · 节点心跳 {{new Date(latestRestockLabelJob.last_heartbeat_at).toLocaleTimeString('zh-CN')}}</template></small>
        <small v-if="latestRestockLabelJob.is_retry_scheduled&&latestRestockLabelJob.next_attempt_at">已尝试 {{latestRestockLabelJob.attempt_count}} 次 · {{new Date(latestRestockLabelJob.next_attempt_at).toLocaleString('zh-CN')}} 后自动重试</small>
        <small v-else-if="latestRestockLabelJob.status==='succeeded'">{{latestRestockLabelJob.artifact_count}} 个 SKU 的 BTW / PDF + PI 已归档</small>
        <small v-else-if="latestRestockLabelJob.status==='failed'">{{latestRestockLabelJob.last_error_message||'等待检查失败原因'}}</small>
      </template>
      <template v-else>
        <strong>蓝标生成</strong>
        <p>从已确认备货快照生成固定任务；不会重新计算库存，也不会让执行器猜 SKU 或数量。</p>
      </template>
    </div>
    <div class="section-actions">
      <button v-if="canOperate&&!latestRestockLabelJob" type="button" class="button primary" :disabled="blueLabelJobSubmitting" @click="requestBlueLabelJob">{{blueLabelJobSubmitting?'排队中…':'一键生成蓝标'}}</button>
      <a v-if="latestRestockLabelJob?.has_pi&&latestRestockPlan" class="button ghost" :href="warehousePath+'/restock-plans/'+latestRestockPlan.id+'/blue-label-jobs/'+latestRestockLabelJob.id+'/download/pi'">下载 PI</a>
      <a v-if="latestRestockLabelJob?.has_package&&latestRestockPlan" class="button primary" :href="warehousePath+'/restock-plans/'+latestRestockPlan.id+'/blue-label-jobs/'+latestRestockLabelJob.id+'/download/package'">下载完整包</a>
    </div>
  </div>
  <template v-if="restockProjection">
    <div class="shipment-kpis restock-kpis"><article><span>最终备货</span><strong>{{restockProjection.summary.final_units}}</strong><small>公式 + 人工补充</small></article><article><span>公式应备</span><strong>{{restockProjection.summary.formula_units}}</strong><small>120 天真实 Shipment</small></article><article><span>人工补充</span><strong>{{restockProjection.summary.manual_units}}</strong><small>新品 / 缺货修正</small></article><article><span>需备货 SKU</span><strong>{{restockProjection.summary.products_to_restock}}</strong><small>最终数量 &gt; 0</small></article></div>
    <div class="toolbar restock-toolbar"><div class="search"><span>⌕</span><input v-model="restockQuery" placeholder="搜索 SKU / 产品名称"></div><span class="restock-rule">最终 = 公式应备 + 人工补充</span></div>
    <div class="table-shell"><table class="restock-table"><thead><tr><th v-for="column in visibleRestockColumns" :key="column.key" class="sortable-header" @click="setRestockSort(column.key)">{{column.label}} <span>{{restockSortMark(column.key)}}</span></th><ColumnSettingsHeader :columns="restockColumns" :required-keys="['final','formula','manual']" :sync-state="restockSyncState" @toggle="toggleRestockColumn" @start-drag="startRestockColumnDrag" @drop="dropRestockColumn" @reset="resetRestockColumns" /></tr></thead><tbody>
      <tr v-for="row in sortedRestockRows" :key="row.product_id" :class="{'restock-needed':row.final_restock_qty>0}"><td v-for="column in visibleRestockColumns" :key="column.key"><template v-if="column.key==='final'"><strong class="restock-final">{{row.final_restock_qty}}</strong></template><template v-else-if="column.key==='formula'"><strong>{{row.formula_restock_qty}}</strong><small>{{row.shipped_120d_qty}} - {{row.quantity_available}}</small></template><template v-else-if="column.key==='manual'"><input class="restock-manual-input" type="number" min="0" :value="row.manual_restock_qty" :disabled="!canOperate" @change="saveManualRestock(row,$event)"></template><template v-else-if="column.key==='sku'"><strong>{{row.sku}}</strong></template><template v-else-if="column.key==='label_sku'"><strong>{{row.label_sku}}</strong><small v-if="row.label_sku_is_override">独立蓝标 SKU</small></template><template v-else-if="column.key==='name'">{{row.name}}</template><template v-else-if="column.key==='units_per_carton'">{{row.units_per_carton===null?'—':`${row.units_per_carton} 个/箱`}}</template><template v-else-if="column.key==='shipped120'">{{row.shipped_120d_qty}}</template><template v-else-if="column.key==='available'">{{row.quantity_available}}</template><template v-else-if="column.key==='on_hand'">{{row.quantity_on_hand}}</template><template v-else-if="column.key==='reserved'">{{row.quantity_reserved}}</template><template v-else-if="column.key==='weight'">{{row.logistics_weight_kg===null?'—':`${Number(row.logistics_weight_kg).toFixed(3)} kg`}}</template><template v-else>{{row.weight_source}}</template></td><td></td></tr>
      <tr v-if="!sortedRestockRows.length"><td :colspan="visibleRestockColumns.length+1" class="empty">没有符合条件的产品</td></tr>
    </tbody></table></div>
  </template>
</section>
<section v-if="activeTab==='inventory' && inventoryMode==='stock'" class="primary-panel">
  <div class="section-heading"><div><p class="section-kicker">CURRENT INVENTORY</p><h3>目前仓库产品库存统计</h3><p>日常库存查看放在页面第一优先级；搜索 SKU、产品名称或库位即可快速定位。</p></div><div class="section-actions"><Link class="button ghost" href="/inventory/products">全部产品库存</Link><Link class="button primary" href="/inventory/sync">导入 / 更新库存</Link></div></div>
  <div class="toolbar"><div class="search"><span>⌕</span><input v-model="query" placeholder="搜索 SKU、产品或库位"></div><select v-model="statusFilter"><option value="all">全部状态</option><option value="in_stock">库存正常</option><option value="low_stock">库存紧张</option><option value="out_of_stock">无货</option></select><span class="result-count">{{filteredItems.length}} / {{warehouse.inventories.length}} SKU</span></div>
  <div class="table-shell"><table class="inventory-table"><thead><tr><th>SKU / 产品</th><th>可用库存</th><th>当前</th><th>预留</th><th>库位</th><th>最近入库</th><th>库存状态</th><th>90 天发货</th><th>建议补货</th><th v-if="canOperate">操作</th></tr></thead><tbody>
    <tr v-for="i in filteredItems" :key="i.id"><td><strong>{{i.product.sku}}</strong><small>{{i.product.name}}</small></td><td class="quantity">{{i.quantity_available}}</td><td>{{i.quantity_on_hand}}</td><td>{{i.quantity_reserved}}</td><td>{{i.location||'—'}}</td><td>{{i.inbound_at||'—'}}</td><td><span class="stock-badge" :class="`stock-${i.stock_status}`">{{i.stock_status_label}}</span></td><td>{{i.replenishment.shipped_90d_qty}}</td><td>{{i.replenishment.recommended_restock_qty===null?i.replenishment.policy_label:`${i.replenishment.policy_label} · ${i.replenishment.recommended_restock_qty}`}}</td><td v-if="canOperate" class="row-actions"><button v-if="!isClearanceProduct(i.product.id)" class="text-button" :disabled="clearanceAddingProductId===i.product.id" @click="addInventoryItemToClearance(i)">{{clearanceAddingProductId===i.product.id?'加入中…':'加入清仓'}}</button><span v-else class="clearance-row-state">已在清仓</span><button class="text-button" @click="quick(i)">保存</button></td></tr>
    <tr v-if="!filteredItems.length"><td :colspan="canOperate?10:9" class="empty">没有符合当前筛选条件的库存商品</td></tr>
  </tbody></table></div>
</section>
<section v-if="activeTab==='costs'" class="primary-panel cost-center-panel">
  <div class="section-heading"><div><p class="section-kicker">WAREHOUSE COSTS</p><h3>最近 3 个月仓库费用</h3><p>仓库费用按真实发生月份汇总；支持手工记录与真实仓库账单导入，导入证据不可通过手工入口删除。</p></div></div>
  <div class="month-tabs"><button v-for="month in costCenter.months" :key="month.month" type="button" :class="{active:selectedCostMonth===month.month}" @click="selectedCostMonth=month.month">{{month.label}}</button></div>
  <template v-if="selectedCost">
    <div v-if="selectedCost.currencies.length" class="cost-currency-list">
      <div v-for="summary in selectedCost.currencies" :key="summary.currency" class="cost-currency-block">
        <div class="cost-currency-title"><strong>{{summary.currency}}</strong><span v-if="summary.other">Other {{money(summary.other)}}</span></div>
        <div class="cost-kpis"><article><span>Total</span><strong>{{money(summary.total)}}</strong></article><article><span>Shipping / 运费</span><strong>{{money(summary.shipping)}}</strong></article><article><span>Parcel Outbound / 出库处理</span><strong>{{money(summary.parcel_outbound)}}</strong></article><article><span>Storage / 仓储费</span><strong>{{money(summary.storage)}}</strong></article></div>
      </div>
    </div>
    <div v-else class="cost-empty">{{selectedCost.label}} 暂无仓库费用记录</div>
    <div v-if="selectedCost.entries.length" class="table-shell cost-table"><table><thead><tr><th>费用类型</th><th>金额</th><th>币种</th><th>备注</th><th>来源</th><th v-if="canManage">操作</th></tr></thead><tbody><tr v-for="entry in selectedCost.entries" :key="entry.id"><td>{{entry.category_label}}</td><td class="quantity">{{money(entry.amount)}}</td><td>{{entry.currency}}</td><td>{{entry.note||'—'}}</td><td>{{entry.source_type==='manual'?'手工录入':'账单导入'}}</td><td v-if="canManage"><button v-if="entry.source_type==='manual'" type="button" class="text-button danger" @click="removeCost(entry)">删除</button><span v-else>—</span></td></tr></tbody></table></div>
  </template>
  <details v-if="canManage && warehouse.bill_import" class="cost-import-panel">
    <summary><div><strong>导入 {{warehouse.bill_import?.label}} 仓库账单</strong><small>一次性操作 · {{warehouse.bill_import?.format_label}} → 预览 → 确认导入</small></div><span>展开</span></summary>
    <div class="cost-import-body">
      <form class="bill-upload" @submit.prevent="previewBill"><label>{{warehouse.bill_import?.label}} {{warehouse.bill_import?.format_label}}<input type="file" :accept="warehouse.bill_import?.accept" @change="selectBill"></label><button class="button ghost" :disabled="!bill.bill||bill.processing">生成预览</button></form>
      <p v-if="bill.errors.bill" class="import-error">{{bill.errors.bill}}</p>
      <div v-if="billImportPreview" class="bill-preview">
        <div class="bill-preview-head"><div><span>Invoice</span><strong>{{billImportPreview.invoice_number||billImportPreview.original_filename}}</strong><small>{{billImportPreview.invoice_date||'—'}} · {{billImportPreview.currency}}</small></div><div><span>账单总额</span><strong>{{billImportPreview.invoice_total}}</strong><small>{{billImportPreview.counts.total}} 条费用证据</small></div></div>
        <div class="bill-preview-grid"><article><span>Shipping</span><strong>{{billImportPreview.shipping_total}}</strong><small>{{billImportPreview.counts.shipping}} 笔 · {{billPeriod('shipping')}}</small></article><article><span>Parcel Outbound</span><strong>{{billImportPreview.parcel_outbound_total}}</strong><small>{{billImportPreview.counts.parcel_outbound}} 笔 · {{billPeriod('parcel_outbound')}}</small></article><article><span>Storage</span><strong>{{billImportPreview.storage_total}}</strong><small>{{billImportPreview.counts.storage}} 笔 · {{billPeriod('storage')}}</small></article></div>
        <div class="bill-monthly"><span v-for="month in billImportPreview.monthly" :key="month.month"><b>{{month.month}}</b> {{month.total}} {{billImportPreview.currency}}</span></div>
        <div class="import-actions"><span v-if="billImportPreview.already_applied" class="import-applied">该源文件已导入</span><button v-else class="button primary" type="button" :disabled="billApply.processing" @click="applyBill">确认导入账单</button></div>
      </div>
    </div>
  </details>
  <div v-if="warehouse.is_fulfillment_warehouse && warehouse.bill_import_onboarding" class="bill-onboarding" :class="warehouse.bill_import_onboarding.status">
    <div><span>Warehouse Bill Provider</span><strong>{{warehouse.bill_import_onboarding.status==='active'?'Active · 已接入':'Awaiting bill sample · 待接入'}}</strong><small>{{warehouse.bill_import_onboarding.label}} · {{warehouse.bill_import_onboarding.format_label}}</small></div>
    <div class="bill-onboarding-note"><b>{{warehouse.bill_import_onboarding.provider?`Provider: ${warehouse.bill_import_onboarding.provider}`:'Provider: 待真实样本确认'}}</b><p>{{warehouse.bill_import_onboarding.note}}</p></div>
  </div>
  <section v-if="billReconciliationHistory.length" class="reconciliation-panel">
    <div class="reconciliation-head"><div><strong>真实物流成本核销</strong><small>Warehouse Bill → Shipment → Order → Accounting；只接受确定匹配，Review / Excluded 不会被猜测写入。</small></div><span>{{billReconciliationHistory.length}} 个最近账单批次</span></div>
    <div v-if="billReconciliationDashboard" class="reconciliation-dashboard">
      <div class="cost-kpis"><article><span>账单批次</span><strong>{{billReconciliationDashboard.totals.batches}}</strong><small>{{billReconciliationDashboard.totals.rows}} 条真实费用证据</small></article><article><span>Shipment 匹配</span><strong>{{billReconciliationDashboard.mode==='lightweight'?'按需':billReconciliationDashboard.totals.matched_shipments}}</strong><small>{{billReconciliationDashboard.mode==='lightweight'?'点击具体账单后计算':billReconciliationDashboard.totals.matched_orders+' 个真实订单'}}</small></article><article><span>核销状态</span><strong>{{billReconciliationDashboard.mode==='lightweight'?'按需':billReconciliationDashboard.totals.ready+' / '+billReconciliationDashboard.totals.review}}</strong><small>{{billReconciliationDashboard.mode==='lightweight'?'首屏不重复跑 Shipment reconciliation':billReconciliationDashboard.totals.excluded+' Excluded'}}</small></article><article><span>Accounting Delta</span><strong>{{billReconciliationDashboard.accounting_delta.enabled?'AUTO':'DRY'}}</strong><small>{{billReconciliationDashboard.accounting_delta.gate}} · {{billReconciliationDashboard.accounting_delta.candidate_count||0}} candidates</small></article></div>
      <div v-if="billReconciliationDashboard.months.length" class="bill-monthly"><span v-for="month in billReconciliationDashboard.months" :key="month.month"><b>{{month.month}}</b> {{Object.entries(month.currencies).map(([c,a])=>`${c} ${a}`).join(' · ')}} · {{month.status==='on_demand'?'账单已导入 · 核销按需计算':reconciliationStatus(month.status)}}</span></div>
      <details v-if="billReconciliationDashboard.review_queue.length" class="cost-import-panel"><summary><div><strong>Review / Excluded 队列</strong><small>{{billReconciliationDashboard.review_queue.length}} 条需要人工确认或明确排除的物流费用</small></div><span>展开</span></summary><div class="table-shell"><table><thead><tr><th>账单</th><th>费用</th><th>Tracking / Order Ref</th><th>决策</th><th>原因</th><th>目标</th></tr></thead><tbody><tr v-for="row in billReconciliationDashboard.review_queue" :key="`${row.batch_id}-${row.category}-${row.tracking_number||row.source_order_references.join('-')}`"><td>{{row.invoice_number||`Batch #${row.batch_id}`}}</td><td>{{row.category}} · {{row.currency}} {{row.amount}}</td><td>{{row.tracking_number||row.source_order_references.join(', ')||'—'}}</td><td>{{row.decision}}</td><td>{{row.reason_code||'—'}}</td><td>Shipment {{row.shipment_id||'—'}} · Order {{row.order_id||'—'}}</td></tr></tbody></table></div></details>
    </div>
    <p v-if="reconciliationApply.errors.reconciliation" class="import-error">{{reconciliationApply.errors.reconciliation}}</p>
    <div v-if="billReconciliationPreview" class="reconciliation-preview">
      <div><span>Batch #{{billReconciliationPreview.batch_id}}</span><strong>核销预览已锁定</strong><small>确认时会重新计算 source + plan；任何漂移立即 fail-close。</small></div>
      <div class="reconciliation-counts"><span>Shipping <b>{{billReconciliationPreview.shipping.ready}}</b> ready / <em>{{billReconciliationPreview.shipping.review}}</em> review / {{billReconciliationPreview.shipping.excluded}} excluded</span><span>Handling <b>{{billReconciliationPreview.parcel_outbound.ready}}</b> ready / <em>{{billReconciliationPreview.parcel_outbound.review}}</em> review / {{billReconciliationPreview.parcel_outbound.excluded}} excluded</span><span>Storage <b>{{billReconciliationPreview.storage.ready_count}}</b> ready / <em>{{billReconciliationPreview.storage.review_count}}</em> review / {{billReconciliationPreview.storage.excluded_count}} excluded</span></div>
      <button v-if="canManage" class="button primary" type="button" :disabled="reconciliationApply.processing" @click="applyReconciliation">确认核销真实物流成本</button>
    </div>
    <div class="table-shell"><table class="reconciliation-table"><thead><tr><th>账单</th><th>金额</th><th>费用明细</th><th>匹配状态</th><th>Review / Excluded</th><th v-if="canManage">操作</th></tr></thead><tbody>
      <tr v-for="batch in billReconciliationHistory" :key="batch.id"><td><strong>{{batch.invoice_number||`Batch #${batch.id}`}}</strong><small>{{batch.provider}} · {{batch.invoice_date||'—'}}</small></td><td><strong>{{batch.currency}} {{batch.invoice_total}}</strong><small>{{batch.total_rows}} 条账单证据</small></td><td><small>Shipping {{batch.shipping_total}} · Handling {{batch.parcel_outbound_total}} · Storage {{batch.storage_total}}</small></td><td><span class="reconciliation-status" :class="batch.reconciliation?.status||'on-demand'">{{batch.supported?(batch.reconciliation?reconciliationStatus(batch.reconciliation.status):'按需核销'):'待接 Provider Adapter'}}</span></td><td><template v-if="batch.reconciliation?.shipping"><strong class="review-number">{{(batch.reconciliation.shipping.review||0)+(batch.reconciliation.parcel_outbound?.review||0)+(batch.reconciliation.storage?.review_count||0)}}</strong><small>Review · {{(batch.reconciliation.shipping.excluded||0)+(batch.reconciliation.parcel_outbound?.excluded||0)+(batch.reconciliation.storage?.excluded_count||0)}} Excluded</small></template><span v-else>点击预览后计算</span></td><td v-if="canManage"><button v-if="batch.supported" type="button" class="text-button" @click="previewReconciliation(batch)">计算核销预览</button><span v-else>—</span></td></tr>
    </tbody></table></div>
  </section>
  <form v-if="canManage" class="cost-entry-form" @submit.prevent="saveCost"><label>费用月份<input v-model="cost.cost_month" type="month" required></label><label>费用类型<select v-model="cost.category"><option value="shipping">Shipping / 运费</option><option value="parcel_outbound">Parcel Outbound / 出库处理</option><option value="storage">Storage / 仓储费</option><option value="other">Other / 其他</option></select></label><label>金额<input v-model.number="cost.amount" type="number" step="0.01" required></label><label>币种<input v-model="cost.currency" maxlength="3" placeholder="USD" required></label><label class="cost-note">备注<input v-model="cost.note" maxlength="255" placeholder="例如：2026-09 月度仓储费"></label><button class="button primary" :disabled="cost.processing">记录费用</button></form>
</section>
<details v-if="activeTab==='config'" class="secondary-panel">
  <summary><div><p class="section-kicker">SHIPPING RULES</p><strong>仓库运费规则</strong><small>{{billing.billing_markdown?'已配置规则 · 展开查看或编辑':'尚未配置 · 展开后录入真实规则'}}</small></div><span>展开</span></summary>
  <div class="details-body config-body"><div class="config-intro"><div><b>运费与计费规则</b><p>这里只维护仓库提供的真实计费规则；P3/P4 的账单费用不会写在这里。</p></div><span class="config-status" :class="{complete:!!billing.billing_markdown}">{{billing.billing_markdown?'已配置':'待配置'}}</span></div><pre class="markdown">{{billing.billing_markdown||'暂无运费规则。可在下方粘贴仓库提供的 Markdown 规则。'}}</pre><form v-if="canManage" class="config-editor" @submit.prevent="saveBilling"><label>编辑规则<textarea v-model="billing.billing_markdown" rows="10" placeholder="粘贴或编辑 Markdown 计费规则"></textarea></label><div class="form-actions"><button class="button primary" :disabled="billing.processing">保存运费规则</button></div></form></div>
</details>
<details v-if="activeTab==='config'" class="secondary-panel">
  <summary><div><p class="section-kicker">WAREHOUSE PROFILE</p><strong>仓库资料</strong><small>{{warehouse.name}} · {{warehouse.city||warehouse.country_code||'地址待补充'}} · 资料完整度 {{profileCompleteness}}%</small></div><span>展开</span></summary>
  <div class="details-body profile-body"><div class="profile-summary"><div><span>仓库代码</span><strong>{{warehouse.code}}</strong></div><div><span>真实地址</span><strong>{{warehouseAddress}}</strong></div><div><span>服务范围</span><strong>{{(warehouse.service_regions||[]).join(', ')||'未配置'}}</strong></div><div><span>运营状态</span><strong>{{warehouse.is_active?'启用':'停用'}} · {{warehouse.ownership_type==='owned'?'自有仓':'外部仓'}}</strong></div></div><form v-if="canManage" class="profile-form" @submit.prevent="saveMeta">
  <fieldset><legend>基础信息</legend><p class="fieldset-note">保留 Warehouse Master 的完整基础字段，不因新版页面精简而删除配置能力。</p><div class="profile-grid"><label>仓库名称<input v-model="meta.name"></label><label>仓库代码<input v-model="meta.code"></label><label>国家 / 地区<input v-model="meta.country_code" maxlength="2"></label><label>时区<input v-model="meta.timezone" placeholder="America/Los_Angeles"></label></div></fieldset>
  <fieldset><legend>真实地址</legend><p class="fieldset-note">真实地址未知时留空，不填写猜测值。</p><div class="profile-grid"><label class="wide">地址 1<input v-model="meta.address_line1"></label><label class="wide">地址 2<input v-model="meta.address_line2"></label><label>城市<input v-model="meta.city"></label><label>州 / 省<input v-model="meta.state_region"></label><label>邮编<input v-model="meta.postal_code"></label></div></fieldset>
  <fieldset><legend>运营参数</legend><div class="profile-grid"><label>仓库归属<select v-model="meta.ownership_type"><option value="owned">自有仓</option><option value="external">外部仓</option></select></label><label>国内发货仓<select v-model="meta.is_domestic"><option :value="true">是</option><option :value="false">否</option></select></label><label>优先级<input v-model.number="meta.priority" type="number" min="0"></label><label>状态<select v-model="meta.is_active"><option :value="true">启用</option><option :value="false">停用</option></select></label><label>预计可发货日期<input v-model="meta.fulfillment_available_on" type="date"><small>日期未到前禁止自动分仓；日期到后仍需 Full Snapshot。</small></label></div></fieldset>
  <fieldset><legend>补货参数</legend><p class="fieldset-note">补货周期 + 安全库存决定补货点；目标覆盖决定建议补货后的目标库存。</p><div class="profile-grid"><label>补货周期（天）<input v-model.number="meta.replenishment_lead_time_days" type="number" min="0" max="365" placeholder="未配置"></label><label>安全库存（天）<input v-model.number="meta.replenishment_safety_stock_days" type="number" min="0" max="365" placeholder="未配置"></label><label>目标覆盖（天）<input v-model.number="meta.replenishment_target_cover_days" type="number" min="0" max="365" placeholder="未配置"></label></div></fieldset>
  <div class="form-actions"><button class="button primary" :disabled="meta.processing">保存全部仓库资料</button></div></form><p v-else class="readonly-profile">{{warehouseAddress}}</p>
  <div class="region-block"><div><h4>服务国家 / 地区</h4><p>完整保留原服务范围配置；仅记录仓库确认可服务的国家，不根据订单或历史数据猜测。</p></div><form v-if="canManage" class="inline-form" @submit.prevent="saveRegions"><input v-model="regions.country_codes" placeholder="US, CA, DE"><button class="button ghost" :disabled="regions.processing">保存服务范围</button></form><p v-else>{{(warehouse.service_regions||[]).join(', ')||'未配置'}}</p></div></div>
</details>
<details v-if="activeTab==='config' && canOperate" class="secondary-panel"><summary><div><p class="section-kicker">MANUAL STOCK</p><strong>手工增加 / 更新产品库存</strong><small>保留原有人工库存能力，日常无需展开。</small></div><span>展开</span></summary><form class="details-body stock-grid" @submit.prevent="addStock"><label>SKU / 产品<InventorySkuCombobox v-model="stock.sku" v-model:product-id="stock.product_id"/></label><label>当前库存<input v-model.number="stock.quantity_on_hand" type="number" min="0"></label><label>预留<input v-model.number="stock.quantity_reserved" type="number" min="0"></label><label>上架时间<input v-model="stock.inbound_at" type="date"></label><label>Location<input v-model="stock.location"></label><label>Standard QoH<input v-model.number="stock.standard_qoh" type="number" min="0"></label><label>预计备货<input v-model.number="stock.expected_restock_qty" type="number" min="0"></label><button class="button primary" :disabled="!stock.product_id">保存库存</button></form></details>
<section v-if="activeTab==='inventory' && inventoryMode==='clearance'" class="clearance-section"><div class="secondary-content"><div class="clearance-heading"><div><h3>清仓 / Gift 库</h3><p>加入清仓后自动成为本仓 Gift 候选；实际是否可选始终读取实时可用库存。</p></div></div><form v-if="canOperate" class="clearance-add" @submit.prevent="addClearance"><div class="clearance-picker"><input v-model="clearanceQuery" placeholder="搜索本仓库存 SKU / 商品"><div class="candidate-list"><label v-for="candidate in filteredClearanceCandidates" :key="candidate.product_id"><input v-model="clearance.product_ids" type="checkbox" :value="candidate.product_id"><strong>{{candidate.sku}}</strong><span>{{candidate.name}}</span><small>可用 {{candidate.quantity_available}}</small></label></div></div><button class="button primary" :disabled="!clearance.product_ids.length||clearance.processing">加入清仓商品</button></form><div class="table-shell"><table><thead><tr><th>SKU</th><th>商品</th><th>可用库存</th><th>Gift 优先级</th><th>状态</th><th v-if="canOperate">操作</th></tr></thead><tbody><tr v-for="item in clearanceProducts" :key="item.id"><td><strong>{{item.product.sku}}</strong></td><td>{{item.product.name}}</td><td>{{item.quantity_available??'—'}}</td><td><input class="priority-input" type="number" min="1" max="9999" :value="item.priority" :disabled="!canOperate" @change="updateClearancePriority(item,$event)"></td><td>{{item.status_label}}</td><td v-if="canOperate"><button class="text-button danger" @click="removeClearance(item)">移出</button></td></tr></tbody></table></div></div>
</section>
</section>
</AuthenticatedLayout>
